// build-icons.mjs — turn the installed Tabler icon package into the runtime table.
//
//   npm --workspace @content-os/engine-production run icons
//
// Source: the `@tabler/icons` npm package (MIT, https://tabler.io/icons). We read
// its pre-parsed `tabler-nodes-outline.json` (every icon's <path d> geometry, no
// SVG parsing) and write `src/diagrams/icons.generated.mjs` — a plain JS object the
// runtime reads with no fs, no network and no dependency, so rendering stays
// deterministic and dependency-free.
//
// The generated file is NOT committed (see .gitignore): the whole ~5,000-icon
// library is available without bloating the repo. It is produced on install
// (package `prepare`) and can be rebuilt any time with the command above.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PKG_ROOT = path.resolve(__dirname, '..');
const OUT = path.join(PKG_ROOT, 'src', 'diagrams', 'icons.generated.mjs');

// Resolve the installed package by walking up the tree (its `exports` map does
// not expose package.json, so require.resolve cannot reach it).
function findTabler() {
  let dir = PKG_ROOT;
  for (;;) {
    const candidate = path.join(dir, 'node_modules', '@tabler', 'icons', 'tabler-nodes-outline.json');
    if (fs.existsSync(candidate)) return candidate;
    const parent = path.dirname(dir);
    if (parent === dir) throw new Error('@tabler/icons not installed — run npm install');
    dir = parent;
  }
}

const NODES = findTabler();

// Our stable public keys -> the upstream Tabler icon name. Kept so plans and
// diagrams authored against the old 10-icon set keep resolving. An alias only
// adds a key; it never removes an upstream name (except where it deliberately
// shadows one — noted inline).
const ALIASES = {
  doc: 'file-text',
  gear: 'settings',
  chart: 'chart-bar',
  chat: 'message', // old key drew the message glyph
};

const nodes = JSON.parse(fs.readFileSync(NODES, 'utf8'));

/** Every drawable path `d` for an icon, dropping non-stroked (fill-only) paths. */
function pathsFor(entry) {
  return entry
    .filter(([type, attrs]) => type === 'path' && attrs.stroke !== 'none' && typeof attrs.d === 'string')
    .map(([, attrs]) => attrs.d.trim())
    .filter((d) => /^[Mm]/.test(d));
}

const table = {};
for (const [name, entry] of Object.entries(nodes)) {
  const paths = pathsFor(entry);
  if (paths.length) table[name] = paths;
}
for (const [alias, target] of Object.entries(ALIASES)) {
  if (table[target]) table[alias] = table[target];
}

const names = Object.keys(table).sort();
const body = names
  .map((name) => `  ${JSON.stringify(name)}: [${table[name].map((d) => JSON.stringify(d)).join(', ')}],`)
  .join('\n');

const out = `// icons.generated.mjs — GENERATED by tools/build-icons.mjs. DO NOT EDIT.
//
// Icon geometry is sourced from the @tabler/icons package (MIT) — https://tabler.io/icons.
// Each entry is a list of SVG path "d" strings on a 24x24 grid. The wrapper
// attributes (viewBox, fill=none, stroke=currentColor, stroke-width=2, round
// caps/joins) are emitted by the engine icon renderer (scene-graph.mjs iconSvg()),
// so only the paths live here.
//
// Not committed (see .gitignore). Regenerate: npm --workspace @content-os/engine-production run icons
export const COMPUTED_ICON_PATHS = {
${body}
};
`;

fs.writeFileSync(OUT, out, 'utf8');
console.log(`icons written: ${OUT}\n  ${names.length} icons (${Object.keys(nodes).length} upstream + ${Object.keys(ALIASES).length} aliases)`);
